<script setup lang="ts">import{ref}from'vue';import{ElMessage}from'element-plus';import{http}from'../api/http';const oldPassword=ref(''),newPassword=ref('');const save=async()=>{try{await http.post('/system/users/me/change-password',{oldPassword:oldPassword.value,newPassword:newPassword.value});ElMessage.success('密码已修改');location.href='/dashboard'}catch(e){ElMessage.error(e instanceof Error?e.message:'修改失败')}}</script><template><el-card class="page-card"><h2>首次登录请修改密码</h2><el-input v-model="oldPassword" type="password" placeholder="旧密码"/><el-input v-model="newPassword" type="password" placeholder="新密码（至少8位，含字母和数字）"/><el-button type="primary" @click="save">保存</el-button></el-card></template>
